const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Times are unix seconds; offset is the spot's UTC offset in seconds, so times show in the spot's local time.
