  const cloudNight = avg(vals(night, 'total')) ?? 50;
  const vis = h.vis;
  const rain24 = sum(vals(win(hours, idx - 24, idx), 'precip'));

  const s1 = clamp((3 - spread) / 3);              // dew point gap closing
  const s2 = clamp((rh - 85) / 12);                // near-saturated air
